import { Form } from '@base-ui/react/form';

afterEach(cleanup);

it('A: controlled remount with empty value leaves filled stale', () => {
  function App() {
    const [show, setShow] = React.useState(true);
    const [k, setK] = React.useState(0);
    return (
      <Field.Root data-testid="root">
        {show && <Field.Control key={k} value={k === 0 ? 'foo' : ''} onValueChange={() => {}} />}
        <button onClick={() => setK(1)}>swap</button>
      </Field.Root>
    );
  }
  render(<App />);
  const root = screen.getByTestId('root');
  console.log('A before', root.hasAttribute('data-filled'));
  fireEvent.click(screen.getByText('swap'));
  console.log('A after swap to empty controlled control: data-filled =', root.hasAttribute('data-filled'));
});

it('C: renders per keystroke controlled onChange validation', () => {
  let renders = 0;
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root validationMode="onChange" validate={() => null}>
        <Field.Control
          data-testid="control"
          value={value}
          onValueChange={setValue}
          render={(props) => {
            renders += 1;
            return <input {...props} />;
          }}
        />
      </Field.Root>
    );
  }
  render(<App />);
  const control = screen.getByTestId('control');
  fireEvent.change(control, { target: { value: 'a' } });
  fireEvent.change(control, { target: { value: 'ab' } });
