  fireEvent.change(c2, { target: { value: 'a' } });
  fireEvent.change(c2, { target: { value: 'ab' } });
  const s2 = renders;
  fireEvent.change(c2, { target: { value: 'abc' } });
  fireEvent.change(c2, { target: { value: 'abcd' } });
  console.log('C uncontrolled onChange renders for 2 keystrokes:', renders - s2);
});

